{

"kind": "propose",
"summary": "Adjust liveness probe timeout and initial delay to accommodate startup time",
"hypotheses": [
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "Liveness probe fails due to short timeout and initial delay, killing app during startup",
        "supporting": ["probe_kills", "killed_during_startup", "ev-target_events"],
        "contradicting": ["probe_timeouts"],
        "missing": ["container_logs_tail"],
        "status": "supported"
    },
    {
        "root_cause_class": "insufficient_evidence",
        "summary": "Need logs to confirm app starts but probe fails before readiness",
        "supporting": ["crashed_on_its_own"],
        "contradicting": ["killed_during_startup"],
        "missing": ["container_logs_tail"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "finance", "name": "ledger", "uid": "uid-deployment-ledger"},
    "params": {
        "container": "app",
        "liveness": {
            "initialDelaySeconds": 20,
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Allow app to start before liveness probe kills it",
    "rationale": "Current liveness probe timeout (1s) is too short for app startup (32s). Increasing timeout to 5s and initial delay to 20s aligns with observed startup time from killed_during_startup evidence.",
    "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events"],
    "cited_predicates": ["killed_during_startup", "probe_kills"]
}
}
